	for _, v := range []int{7, 8, 9} {
		ptrs = append(ptrs, &v)
	}
	fmt.Println(*ptrs[0], *ptrs[1], *ptrs[2])
}

// run
package main

import "fmt"

func upto(n int) func(func(int) bool) {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			if !yield(i) {
				return
			}
		}
	}
}

func main() {
	for v := range upto(5) {
		if v == 3 {
			break
		}
		fmt.Println(v)
	}
	total := 0
	for v := range upto(4) {
		total += v
	}
	fmt.Println(total)
}

