import "fmt"

// A package-level init runs before any test does, and everything it writes is
// written by the *test binary*, not by the `go` command. `go test` captures
// both of the test binary's streams, merges them in the order the program
// wrote them, and emits that text on the `go` command's own standard output,
// ahead of the test report -- it does not pass the binary's standard error
// through to its own. Without -v the same text is discarded when the package
// passes. See section 4 of SPEC/toolchain.md.
func init() {
	println("A: init wrote this to standard error, first")
	fmt.Println("B: init wrote this to standard output, second")
	println("C: init wrote this to standard error, third")
}
